<?php
require_once __DIR__.'/includes/functions.php';require_login();require_once __DIR__.'/config/database.php';$pageTitle='Customers';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['full_name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');if($name===''){flash('danger','Customer name is required.');redirect('customers.php');}if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('danger','Enter a valid email address.');redirect('customers.php');}if($id){$q=$pdo->prepare('UPDATE customers SET full_name=?,phone=?,email=?,address=? WHERE id=?');$q->execute([$name,$phone?:null,$email?:null,$address?:null,$id]);flash('success','Customer updated.');}else{$q=$pdo->prepare('INSERT INTO customers(full_name,phone,email,address) VALUES(?,?,?,?)');$q->execute([$name,$phone?:null,$email?:null,$address?:null]);flash('success','Customer saved to database.');}redirect('customers.php');}if($action==='delete'){try{$q=$pdo->prepare('DELETE FROM customers WHERE id=?');$q->execute([(int)$_POST['id']]);flash('success','Customer deleted.');}catch(PDOException $e){flash('danger','Could not delete customer.');}redirect('customers.php');}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM customers WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$search=trim($_GET['q']??'');if($search!==''){$q=$pdo->prepare('SELECT * FROM customers WHERE full_name LIKE ? OR phone LIKE ? OR email LIKE ? ORDER BY full_name');$like='%'.$search.'%';$q->execute([$like,$like,$like]);$rows=$q->fetchAll();}else{$rows=$pdo->query('SELECT * FROM customers ORDER BY full_name')->fetchAll();}require __DIR__.'/includes/header.php';
?>
<div class="row"><div class="col-md-4"><div class="card card-primary card-outline"><div class="card-header"><h3 class="card-title"><?= $edit?'Edit Customer':'Add Customer' ?></h3></div><form method="post"><div class="card-body"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="form-group"><label class="required">Full name</label><input class="form-control" name="full_name" required value="<?=e($edit['full_name']??'')?>"></div><div class="form-group"><label>Phone</label><input class="form-control" name="phone" value="<?=e($edit['phone']??'')?>"></div><div class="form-group"><label>Email</label><input type="email" class="form-control" name="email" value="<?=e($edit['email']??'')?>"></div><div class="form-group"><label>Address</label><textarea class="form-control" name="address" rows="2"><?=e($edit['address']??'')?></textarea></div></div><div class="card-footer"><button class="btn btn-primary">Save Customer</button><?php if($edit):?> <a href="customers.php" class="btn btn-default">Cancel</a><?php endif;?></div></form></div></div><div class="col-md-8"><div class="card"><div class="card-header"><h3 class="card-title">Customer List</h3><div class="card-tools"><form method="get" class="input-group input-group-sm" style="width:230px"><input name="q" class="form-control" placeholder="Search customers" value="<?=e($search)?>"><div class="input-group-append"><button class="btn btn-default"><i class="fas fa-search"></i></button></div></form></div></div><div class="card-body table-responsive p-0"><table class="table table-hover"><thead><tr><th>Name</th><th>Phone</th><th>Email</th><th>Address</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty-state">No customers found.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['email'])?></td><td><?=e($r['address'])?></td><td class="text-nowrap"><a href="customers.php?edit=<?=(int)$r['id']?>" class="btn btn-xs btn-info"><i class="fas fa-edit"></i></a> <form method="post" class="d-inline"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-xs btn-danger" data-confirm="Delete this customer?"><i class="fas fa-trash"></i></button></form></td></tr><?php endforeach;endif;?></tbody></table></div></div></div></div>
<?php require __DIR__.'/includes/footer.php';?>
